mapper.select:
select user_name
from users
where user_id = #{familyId}

select v.viewing_id as viewing_id, v.child_id as child_id, c.child_name as child_name, v.video_id as video_id, v.watch_time as watch_time, v.watch_duration as watch_duration, a.alert_type as latest_alert_type, a.risk_level as latest_risk_level from viewing_history v left join children c on c.child_id = v.child_id left join lateral ( select alert_type, risk_level from alert_log where viewing_id = v.viewing_id order by alert_id desc limit 1 ) a on true where v.user_id = #{familyId}
and v.child_id = #{childId}
order by v.watch_time desc nulls last, v.viewing_id desc limit #{limit}
